// Existing 120 BPM recording: waveform onset grid is stable across the track.
// 15ms compensates the decoded MP3 onset/encoder lead; never use button time as beat zero.
export const DANCE_GRID=Object.freeze({beatMs:500,originMs:15,barBeats:4,introBeats:8,feedbackBeats:4,loopBeats:448});
export function nextMusicBar(clockMs,grid=DANCE_GRID){const bar=grid.beatMs*grid.barBeats;return grid.originMs+Math.ceil((clockMs-grid.originMs-1e-7)/bar)*bar;}
export function danceSchedule(stages,startClockMs=0,grid=DANCE_GRID){let questionAt=nextMusicBar(startClockMs+grid.introBeats*grid.beatMs,grid);return stages.map(stage=>{const demoAt=questionAt+grid.barBeats*grid.beatMs,demoEnd=demoAt+stage.sequence.length*grid.beatMs,countAt=nextMusicBar(demoEnd,grid),inputAt=countAt+grid.barBeats*grid.beatMs,resultAt=inputAt+stage.sequence.length*grid.beatMs,feedbackEnd=resultAt+grid.feedbackBeats*grid.beatMs,nextAt=nextMusicBar(feedbackEnd,grid),round={questionAt,demoAt,demoEnd,countAt,inputAt,resultAt,feedbackEnd,nextAt};questionAt=nextAt;return round;});}
export function roundFeedback(cells){const correct=cells.filter(s=>s==='correct').length,wrong=cells.filter(s=>s==='wrong').length,miss=cells.filter(s=>s==='miss').length,total=cells.length;if(correct===total)return{outcome:'success',title:'很好！Good!',detail:`全部答對 · ${correct}/${total}`,correct,wrong,miss,total};return{outcome:correct?'partial':'retry',title:correct?'有跟上，再加油！':'沒關係，再跟一次！',detail:`答對 ${correct}/${total} · 按錯 ${wrong} · 漏拍 ${miss}`,correct,wrong,miss,total};}
